fn copy(a: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate a vector of the same length as the input
    let mut b: Vec<u64> = Vec::with_capacity(a.len());
    // Copy each element from `a` into `b`, preserving order
    for &val in a.iter() {
        b.push(val);
    }
    b
}

fn main() {
    let original = vec![10, 20, 30, 40];
    let cloned = copy(&original);
    assert_eq!(original, cloned);
    println!("Original: {:?}, Cloned: {:?}", original, cloned);
}